/** Read the on-device cache of the app settings (written on every save;
 *  the server copy is authoritative and replaces it on load). Lets the
 *  theme/font apply on first paint and keeps Settings instant offline. */
function cachedAppSettings(): AppSettingsT {
  try {
    const raw = localStorage.getItem("tgps-app-settings");
    if (raw) return { ...DEFAULT_APP_SETTINGS, ...(JSON.parse(raw) as Partial<AppSettingsT>) };
  } catch { /* fall through to defaults */ }
  return DEFAULT_APP_SETTINGS;
}

type LoadT = ApiResponse<typeof api, "listLoads">["loads"][number];
