type Maneuver = {
  instruction: string;
  miles: number;
  // Guidance detail straight from the routing response (Valhalla) — a
  // field is present only where the routing data actually carries it.
  // Lane guidance is NEVER fabricated: when the response has no exit /
  // street detail for a maneuver, the UI says so instead of inventing it.
  type: number | null; // Valhalla maneuver type code
  streetNames: string[];
  beginStreetNames: string[];
  exitNumber: string | null;
  exitName: string | null;
  exitToward: string | null;
  exitBranch: string | null;
  verbal: string | null; // verbal_pre_transition_instruction, when given
  // The response's structured sign object (Valhalla `sign`: exit
  // number / branch / toward / name elements), flattened at the
  // parse point — the docked gantry board (placard.ts) reads the
  // sign from here. Null when the response carried no sign object.
  sign: ManeuverSignData | null;
  // Lane record for the maneuver, when the routing source returns
  // one. Valhalla returns NO lane data (verified live 2026-11-05),
  // so this is null on every real route today and the board renders
  // without its lane strip — lanes are never synthesized.
  lanes: PlacardLane[] | null;
};

/** Direction arrow for a maneuver, from the Valhalla type code when the
 *  routing data provides one; falls back to keywords in the instruction
 *  text (which Valhalla always provides). Display only. */
function maneuverArrow(m: Maneuver): string {
  const t = m.type;
  if (t != null) {
    if (t === 4 || t === 5 || t === 6) return "🏁";
    if (t === 12 || t === 13) return "↩️";
    if (t === 9) return "↗️";
    if (t === 10 || t === 20) return "➡️";
    if (t === 11) return "↪️";
    if (t === 14) return "↩️";
    if (t === 15 || t === 21) return "⬅️";
    if (t === 16) return "↖️";
    if (t === 18) return "↗️";
    if (t === 19) return "↖️";
    if (t === 22) return "⬆️";
    if (t === 23) return "⬆️";
    if (t === 25 || t === 26) return "🔄";
    if (t === 1 || t === 2 || t === 3 || t === 8 || t === 17 || t === 24) return "⬆️";
  }
  const s = m.instruction.toLowerCase();
  if (/destination|arrive/.test(s)) return "🏁";
  if (/u-turn/.test(s)) return "↩️";
  if (/slight right|exit right|ramp.*right/.test(s)) return "↗️";
  if (/slight left|exit left|ramp.*left/.test(s)) return "↖️";
  if (/sharp right/.test(s)) return "↪️";
  if (/sharp left/.test(s)) return "↩️";
  if (/\bright\b/.test(s)) return "➡️";
  if (/\bleft\b/.test(s)) return "⬅️";
  if (/roundabout/.test(s)) return "🔄";
  return "⬆️";
}

/** The road the maneuver runs on / turns onto, from routing data only. */
function maneuverStreet(m: Maneuver): string | null {
  const names = m.beginStreetNames.length > 0 ? m.beginStreetNames : m.streetNames;
  return names.length > 0 ? names.join(" / ") : null;
}

/** Exit guidance line, built only from exit fields the routing response
 *  actually returned for this maneuver. Null when it returned none. */
function maneuverExitLine(m: Maneuver): string | null {
  const parts: string[] = [];
  if (m.exitNumber) parts.push(`Exit ${m.exitNumber}`);
  if (m.exitBranch) parts.push(m.exitBranch);
  if (m.exitToward) parts.push(`toward ${m.exitToward}`);
  if (m.exitName && m.exitName !== m.exitToward) parts.push(m.exitName);
  return parts.length > 0 ? parts.join(" · ") : null;
}

type RouteOption = {
  id: number;
  miles: number;
  minutes: number;
  hasToll: boolean;
  coords: [number, number][];
  maneuvers: Maneuver[];
  fuelGal: number;
  fuelCost: number;
  pay: number;
  // Percent-basis note for the route card (e.g. "25% of the $2,000
  // load" or why the cut can't be figured). Null on CPM routes.
  payNote: string | null;
  net: number;
  safetyScore: number | null; // 1..5, null until weather returns
  safetyLabel: string;
  weatherHazards: string[];
  weatherNote: string;
  // Live traffic (TomTom, Gold+ only — Basic never asks): "idle" until
  // the traffic layer answers, "live" with a delay estimate + the
  // fetch time, "unavailable" when TomTom didn't answer (the card then
  // says so and the drive time stays honestly free-flow).
  trafficState: "idle" | "live" | "unavailable";
  trafficDelayMin: number | null;
  trafficAsOf: number | null; // epoch ms of the TomTom data
  // Live traffic GEOMETRY for the map line itself (Apple-style):
  // flow samples along the route (frac + current/free-flow ratio)
  // and on-route incident geometry — trafficSegments.ts turns these
  // into the orange (slow) / red (heavy) stretches painted over the
  // blue route line. Absent until TomTom answers; never invented.
  trafficFlow?: { frac: number; ratio: number | null }[];
  trafficIncidents?: { coords: [number, number][]; magnitude: number; delayMin: number; category: number }[];
  // Stored route elevation (hill grade alerts, 2026-11-08): Valhalla
  // elevation samples in METERS every ELEV_STEP_MI along the route,
  // stitched across legs/sections at plan time and persisted with the
  // route snapshot — grades work offline and after Resume. Null when
  // the routing answer carried no elevation: NO grade UI ever shows
  // for that route (hillGrade.ts — never guessed).
  elevSamplesM: number[] | null;
  elevStepMi: number;
};

/** The Valhalla elevation sampling step: 100 m along the route. */
const ELEV_STEP_MI = 100 / 1609.344;

