// Every major truck-stop brand found in OpenStreetMap brand/name data gets
// its own key, toggle, marker color, and monogram. "truckplaza" is the
// independent truck plazas (tagged/named as truck stops, no chain brand);
// "other" is any other fuel station — selectable like every brand.
type Brand =
  | "loves"
  | "pilot"
  | "ta"
  | "petro"
  | "sapp"
  | "kwik"
  | "caseys"
  | "maverik"
  | "roadranger"
  | "ambest"
  | "bosselman"
  | "truckplaza"
  | "other";

type BrandDef = { key: Brand; label: string; short: string; mono: string; color: string };
const BRANDS: BrandDef[] = [
  { key: "loves", label: "Love's Travel Stops", short: "Love's", mono: "LV", color: "#ef4444" },
  { key: "pilot", label: "Pilot / Flying J", short: "Pilot / Flying J", mono: "PJ", color: "#f97316" },
  { key: "ta", label: "TA TravelCenters", short: "TA", mono: "TA", color: "#3b82f6" },
  { key: "petro", label: "Petro Stopping Centers", short: "Petro", mono: "PT", color: "#a855f7" },
  { key: "sapp", label: "Sapp Bros", short: "Sapp Bros", mono: "SB", color: "#eab308" },
  { key: "kwik", label: "Kwik Trip / Kwik Star", short: "Kwik Trip", mono: "KT", color: "#ec4899" },
  { key: "caseys", label: "Casey's", short: "Casey's", mono: "CS", color: "#22c55e" },
  { key: "maverik", label: "Maverik", short: "Maverik", mono: "MV", color: "#14b8a6" },
  { key: "roadranger", label: "Road Ranger", short: "Road Ranger", mono: "RR", color: "#84cc16" },
  { key: "ambest", label: "Ambest", short: "Ambest", mono: "AM", color: "#38bdf8" },
  { key: "bosselman", label: "Bosselman / Pump & Pantry", short: "Bosselman", mono: "BP", color: "#d946ef" },
  { key: "truckplaza", label: "Truck plazas (independent)", short: "Truck plazas", mono: "TP", color: "#94a3b8" },
  { key: "other", label: "Independent / Other", short: "Independent / Other", mono: "IN", color: "#64748b" },
];
const BRAND_BY_KEY = new Map<Brand, BrandDef>(BRANDS.map((b) => [b.key, b]));

/** Is this brand turned OFF in the driver's profile? Love's/Pilot also keep
 *  their original columns, so a choice saved before the full brand list
 *  existed is honored exactly. */
function brandIsOff(p: ProfileT, b: Brand): boolean {
  if (b === "loves" && p.lovesOff) return true;
  if (b === "pilot" && p.pilotOff) return true;
  return p.brandOffs.includes(b);
}

/** Return a new profile with the brand's on/off state set, keeping the
 *  legacy Love's/Pilot columns in sync. */
function withBrandOff(p: ProfileT, b: Brand, off: boolean): ProfileT {
  const offs = new Set(p.brandOffs);
  if (p.lovesOff) offs.add("loves");
  if (p.pilotOff) offs.add("pilot");
  if (off) offs.add(b);
  else offs.delete(b);
  return {
    ...p,
    lovesOff: offs.has("loves"),
    pilotOff: offs.has("pilot"),
    brandOffs: [...offs],
  };
}

// ---- Fuel-stop brand selection -------------------------------------------
// One selection drives every fuel surface (fuel finder, route view,
// parking planner, map, best-stop pick): "All" shows EVERY stop, or the
// driver picks one or more brands and only those show. The selection is
// stored as the profile's OFF list, so it persists server-side, is
// remembered between opens, and applies to every trip (including every
// queued trip in Multiple Trips) automatically.
const ALL_BRAND_KEYS: Brand[] = BRANDS.map((b) => b.key);

/** The driver's brand selection: null = All (nothing turned off). */
function fuelSelection(p: ProfileT): Brand[] | null {
  const on = ALL_BRAND_KEYS.filter((k) => !brandIsOff(p, k));
  return on.length === ALL_BRAND_KEYS.length ? null : on;
}

/** Profile with the brand selection set (null = All brands on). */
function withFuelSelection(p: ProfileT, sel: Brand[] | null): ProfileT {
  let next = p;
  for (const k of ALL_BRAND_KEYS) {
    next = withBrandOff(next, k, sel != null && !sel.includes(k));
  }
  return next;
}

function FuelBrandPicker({
  profile,
  onSelect,
  compact = false,
}: {
  profile: ProfileT;
  onSelect: (next: ProfileT) => void;
  compact?: boolean;
}) {
  const sel = fuelSelection(profile);
  const tapBrand = (k: Brand) => {
    if (sel == null) {
      // From All, a tap narrows to just this brand.
      onSelect(withFuelSelection(profile, [k]));
    } else if (sel.includes(k)) {
      const next = sel.filter((x) => x !== k);
      onSelect(withFuelSelection(profile, next.length === 0 ? null : next));
    } else {
      onSelect(withFuelSelection(profile, [...sel, k]));
    }
  };
  const chipCls = (active: boolean) =>
    `btn-press flex items-center gap-1.5 rounded-full border px-3 py-2 text-xs font-bold ${active ? "btn-neon border-transparent" : "border-[var(--border)] bg-[var(--surface2)] text-[var(--dim)]"}`;
  return (
    <div aria-label="Fuel stop brand selection">
      <div className="flex flex-wrap gap-1.5" role="group" aria-label="Choose which fuel stop brands to show">
        <button
          type="button"
          aria-pressed={sel == null}
          aria-label="Show all fuel stops — every brand and independents"
          className={chipCls(sel == null)}
          onClick={() => onSelect(withFuelSelection(profile, null))}
        >
          ⛽ All
        </button>
        {BRANDS.map((b) => {
          const active = sel != null && sel.includes(b.key);
          return (
            <button
              key={b.key}
              type="button"
              aria-pressed={active}
              aria-label={`Show ${b.label} fuel stops`}
              className={chipCls(active)}
              onClick={() => tapBrand(b.key)}
            >
              <span
                className="flex h-4 min-w-4 items-center justify-center rounded px-0.5 text-[8px] font-extrabold text-white"
                style={{ background: b.color }}
                aria-hidden
              >
                {b.mono}
              </span>
              {b.short}
            </button>
          );
        })}
      </div>
      <p className="mt-1.5 text-xs text-[var(--dim)]">
        {sel == null
          ? "Showing: ALL fuel stops — every brand plus independents. Tap a brand to see just that chain."
          : `Showing: ${sel.map((k) => BRAND_BY_KEY.get(k)?.short ?? k).join(" + ")} only. The best-stop pick and prices update to match. Tap All to see everything.`}
        {!compact && " Your pick is remembered and applies to every trip."}
      </p>
    </div>
  );
}


// ---- Net-Price Fuel Planner v1 ---------------------------------------------
// Prices come ONLY from the driver's own fuel log, driver-reported
// prices (age + source shown on every price), map tags (age unknown),
// and the labelled EIA weekly snapshot — NEVER a live station feed.
// Net price = pump price − that state's IFTA diesel tax, from the
// app's labelled IFTA rate table (server-side snapshot).
type FuelPriceData = ApiResponse<typeof api, "getFuelPriceData">;
type StopPriceInfo = { price: number; source: string; state: string | null };

function priceAgeLabel(iso: string): string {
  const hrs = Math.max(0, (Date.now() - Date.parse(iso)) / 3600000);
  if (hrs < 1) return "under an hour ago";
  if (hrs < 24) return `${Math.round(hrs)}h ago`;
  return `${Math.round(hrs / 24)}d ago`;
}

// Price-evidence grades (server files every price-layer row with
// one): a fingerprinted receipt outranks a plain logged purchase,
// which outranks a manual report — used only to break freshness ties.
function priceGradeRank(grade: string): number {
  if (grade === "receipt_verified") return 3;
  if (grade === "purchase") return 2;
  if (grade === "reported") return 1;
  return 0;
}

// The honest source label for a price-layer row: it states the grade
// and never says "live". The layer is anonymous — no reporter name
// ever appears in a label.
function reportSourceLabel(r: FuelPriceData["reports"][number]): string {
  if (r.grade === "receipt_verified") return `receipt-verified purchase · ${new Date(r.reportedAt).toLocaleDateString()}`;
  if (r.grade === "purchase") return `logged purchase · ${new Date(r.reportedAt).toLocaleDateString()}`;
  return `reported ${priceAgeLabel(r.reportedAt)} by a driver`;
}

function matchStopPrice(stop: FuelStop, data: FuelPriceData, geocodedState?: string): StopPriceInfo | null {
  const norm = (x: string) => x.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
  const stopName = norm(stop.name);
  const stateFallback = geocodedState && geocodedState !== "—" ? geocodedState : null;
  const nameHit = (name: string | null): boolean => {
    if (!name) return false;
    const stName = norm(name);
    return stName.length >= 4 && (stopName.includes(stName) || stName.includes(stopName));
  };
  // 1) Coordinate-carrying reports within 1.2 mi of this stop (null-
  //    coordinate purchase-derived reports are skipped here — they
  //    match by name + state in step 2). Freshest wins, EXCEPT
  //    reports in the same hour count as equal freshness — among
  //    those, the stronger grade wins (receipt_verified > purchase >
  //    reported). The server returns reports newest-first.
  const coordMatches = data.reports.filter(
    (r) => r.lat != null && r.lon != null && haversineMi(stop, { lat: r.lat, lon: r.lon }) <= 1.2,
  );
  if (coordMatches.length > 0) {
    const hourOf = (iso: string) => Math.floor(Date.parse(iso) / 3600000);
    const best = [...coordMatches].sort((a, b) => {
      const byHour = hourOf(b.reportedAt) - hourOf(a.reportedAt);
      if (byHour !== 0) return byHour;
      return priceGradeRank(b.grade) - priceGradeRank(a.grade);
    })[0];
    if (best) {
      return { price: best.price, source: reportSourceLabel(best), state: best.state ?? stateFallback };
    }
  }
  // 2) Null-coordinate purchase-derived reports: station name + state
  //    must both match this stop (state-level evidence — a purchase
  //    never carries fabricated coordinates). receipt_verified is
  //    considered before plain purchases; within a grade the server's
  //    newest-first order stands.
  if (stateFallback) {
    for (const grade of ["receipt_verified", "purchase"] as const) {
      for (const r of data.reports) {
        if (r.lat != null || r.lon != null) continue;
        if (r.grade !== grade) continue;
        if (!r.state || r.state.trim().toLowerCase() !== stateFallback.trim().toLowerCase()) continue;
        if (!nameHit(r.station)) continue;
        return { price: r.price, source: reportSourceLabel(r), state: r.state };
      }
    }
  }
  // 3) The driver's own fuel log, matched by station name.
  for (const f of data.ownPurchases) {
    if (nameHit(f.station)) {
      return { price: f.pricePerGallon, source: `your fuel log · ${new Date(f.purchasedAt).toLocaleDateString()}`, state: f.state };
    }
  }
  // 4) The map's own price tag (age unknown — labelled as such).
  if (stop.dieselPrice != null) {
    return { price: stop.dieselPrice, source: "map tag — age unknown", state: stateFallback };
  }
  return null;
}

function ReportPriceForm({ stop, stateName, setBanner, onDone }: {
  stop: FuelStop;
  stateName: string | null;
  setBanner: (s: string | null) => void;
  onDone: () => void;
}) {
  const [price, setPrice] = useState("");
  const [busy, setBusy] = useState(false);
  const v = parseFloat(price);
  return (
    <div className="mt-1.5 flex items-center gap-2" aria-label={`Report a diesel price at ${stop.name}`}>
      <input
        className="w-28 rounded-lg bg-[var(--surface)] px-2.5 py-2 text-sm"
        inputMode="decimal"
        placeholder="$/gal"
        value={price}
        aria-label={`Diesel price per gallon at ${stop.name}`}
        onChange={(e) => setPrice(e.target.value)}
      />
      <button
        type="button"
        disabled={busy || !(v > 0.5 && v < 12)}
        className="btn-neon btn-press rounded-lg px-3 py-2 text-xs font-bold disabled:opacity-50"
        aria-label={`Save the reported price at ${stop.name}`}
        onClick={() => {
          setBusy(true);
          void api
            .reportFuelPrice({ station: stop.name, lat: stop.lat, lon: stop.lon, state: stateName, price: v })
            .then((r) => {
              if (r.ok) { setBanner(`Price reported & sealed ✓ — ${stop.name} at $${v.toFixed(3)}/gal. It shows with its age wherever this stop appears.`); onDone(); }
              else setBanner(r.error ?? "That report didn't save — try again.");
            })
            .catch(() => setBanner("That report didn't save — try again."))
            .finally(() => setBusy(false));
        }}
      >
        Report price
      </button>
    </div>
  );
}

type OsmElement = {
  id: number;
  type: string;
  lat?: number;
  lon?: number;
  center?: { lat: number; lon: number };
  tags?: Record<string, string>;
};

type FuelStop = {
  id: string;
  name: string;
  brand: Brand;
  lat: number;
  lon: number;
  alongMi: number;
  offRouteMi: number;
  dieselPrice: number | null;
  truckFriendly: boolean;
  // Amenity facts straight from OSM tags — null means the map data doesn't
  // say, and the UI labels it "unknown" rather than guessing.
  hasDiesel: boolean | null;
  truckParking: boolean | null;
  showers: boolean | null;
  scales: boolean | null;
  // Full card details (truckStop.ts) — parking-space count, address,
  // phone/site/hours, and the whole amenity set for the tap-a-stop
  // card. Same OSM tags, richer read; unknowns stay unknown.
  details: TruckStopDetails;
};

