// ---------- Small helpers ---------------------------------------------------

/** Escape text from external sources (OSM tags, geocoder names) before it
 *  is handed to map popups, which insert strings as HTML. */
function escHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function haversineMi(a: LatLon, b: LatLon): number {
  const R = 3958.8;
  const dLat = ((b.lat - a.lat) * Math.PI) / 180;
  const dLon = ((b.lon - a.lon) * Math.PI) / 180;
  const s =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((a.lat * Math.PI) / 180) *
      Math.cos((b.lat * Math.PI) / 180) *
      Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(s));
}

function fmtMi(n: number): string {
  return n >= 100 ? n.toFixed(0) : n.toFixed(1);
}
function fmtMoney(n: number): string {
  return `$${n.toFixed(2)}`;
}
function fmtDuration(min: number): string {
  const h = Math.floor(min / 60);
  const m = Math.round(min % 60);
  return h > 0 ? `${h}h ${m}m` : `${m}m`;
}
function fmtClock(d: Date): string {
  return d.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
}

function decodePolyline6(str: string): [number, number][] {
  const coords: [number, number][] = [];
  let index = 0;
  let lat = 0;
  let lng = 0;
  while (index < str.length) {
    let shift = 0;
    let result = 0;
    let byte: number;
    do {
      byte = str.charCodeAt(index++) - 63;
      result |= (byte & 0x1f) << shift;
      shift += 5;
    } while (byte >= 0x20);
    lat += result & 1 ? ~(result >> 1) : result >> 1;
    shift = 0;
    result = 0;
    do {
      byte = str.charCodeAt(index++) - 63;
      result |= (byte & 0x1f) << shift;
      shift += 5;
    } while (byte >= 0x20);
    lng += result & 1 ? ~(result >> 1) : result >> 1;
    coords.push([lat / 1e6, lng / 1e6]);
  }
  return coords;
}

/** OSM maxspeed parsing lives in speedLimit.ts with the rest of the
 *  limit-selection logic (unit-tested there). */

/** Parse OSM maxheight ("4.1", "13'6\"", "4.1 m") to feet. */
function parseHeightFt(raw: string | undefined): number | null {
  if (!raw) return null;
  const t = raw.trim();
  const ftIn = t.match(/^(\d+(?:\.\d+)?)'\s*(\d+(?:\.\d+)?)?/);
  if (ftIn) {
    return parseFloat(ftIn[1] ?? "0") + parseFloat(ftIn[2] ?? "0") / 12;
  }
  const num = parseFloat(t.replace(/[^0-9.]/g, ""));
  if (!Number.isFinite(num) || num <= 0) return null;
  if (/ft|feet/i.test(t)) return num;
  return num * 3.28084; // OSM default unit is meters
}

/** Parse OSM maxweight ("40 t", "80,000 lbs", "36.287") to pounds. */
function parseWeightLbs(raw: string | undefined): number | null {
  if (!raw) return null;
  const t = raw.trim().toLowerCase();
  const num = parseFloat(t.replace(/[^0-9.]/g, ""));
  if (!Number.isFinite(num) || num <= 0) return null;
  if (/lbs|pounds|lb/.test(t)) return num;
  if (/kg/.test(t)) return num * 2.20462;
  if (/st\b/.test(t)) return num * 2240; // short tons unlikely; treat as US ton below
  if (/t|ton/.test(t)) return num * 2204.62; // metric tonnes (OSM default)
  // Bare number in OSM maxweight is metric tonnes.
  return num * 2204.62;
}

function detectBrand(tags: Record<string, string>): Brand {
  const hay = `${tags.brand ?? ""} ${tags.name ?? ""} ${tags.operator ?? ""}`.toLowerCase();
  // Specific chains first — order matters (e.g. "TA Petro" locations carry
  // both names; the Petro brand wins its own stops).
  if (hay.includes("pilot") || hay.includes("flying j")) return "pilot";
  if (hay.includes("love")) return "loves";
  if (hay.includes("petro")) return "petro";
  if (hay.includes("travelcenters") || hay.includes("travel centers of america")) return "ta";
  if (/\bta\b/.test(hay) && /(travel|truck|express|stopping)/.test(hay)) return "ta";
  if (hay.includes("sapp")) return "sapp";
  if (hay.includes("kwik")) return "kwik";
  if (hay.includes("casey")) return "caseys";
  if (hay.includes("maverik")) return "maverik";
  if (hay.includes("road ranger")) return "roadranger";
  if (hay.includes("ambest")) return "ambest";
  if (hay.includes("bosselman") || hay.includes("pump & pantry") || hay.includes("pump n pantry")) return "bosselman";
  // Independent truck plazas: named/tagged as truck stops without a chain.
  const name = (tags.name ?? "").toLowerCase();
  if (
    tags.truck_stop === "yes" ||
    name.includes("truck stop") ||
    name.includes("truckstop") ||
    name.includes("truck plaza") ||
    name.includes("travel plaza") ||
    name.includes("travel center") ||
    name.includes("travel centre") ||
    name.includes("travel stop") ||
    (tags.hgv === "yes" && name.includes("truck"))
  ) {
    return "truckplaza";
  }
  return "other";
}
