function DonateSheet({ onClose }: { onClose: () => void }) {
  const [copied, setCopied] = useState<string | null>(null);
  const [copyFailed, setCopyFailed] = useState<string | null>(null);
  return (
    <InfoSheetShell title="💝 Support STONEMILES" ariaLabel="Donation wallets" onClose={onClose}>
      <p className="mt-1 text-sm leading-relaxed text-[var(--dim)]">
        Donations are voluntary gifts to the project — they keep the maps, servers, and development rolling.
        They are never required, they buy nothing, and no feature is locked behind them.
      </p>
      <div className="mt-3 space-y-2">
        {DONATION_WALLETS.map((w) => (
          <div key={w.network} className="rounded-xl bg-[var(--surface2)] px-3 py-3">
            <div className="flex items-center justify-between gap-2">
              <span className="text-xs font-bold uppercase tracking-wide text-[var(--dim)]">{w.network}</span>
              <button
                type="button"
                className="shrink-0 rounded-lg bg-[var(--surface)] px-3 py-1.5 text-xs font-bold"
                aria-label={`Copy the ${w.network} donation address`}
                onClick={() => {
                  setCopyFailed(null);
                  try {
                    void navigator.clipboard
                      .writeText(w.address)
                      .then(() => setCopied(w.network))
                      .catch(() => setCopyFailed(w.network));
                  } catch {
                    setCopyFailed(w.network);
                  }
                }}
              >
                {copied === w.network ? "Copied ✓" : "Copy"}
              </button>
            </div>
            <p className="mt-1.5 break-all font-mono text-sm leading-relaxed">{w.address}</p>
            {copyFailed === w.network && (
              <p className="mt-1 text-xs font-semibold text-[var(--danger)]">Copy didn't work on this device — long-press the address to copy it by hand.</p>
            )}
            <p className="mt-1 text-xs text-[var(--dim)]">Send only on the {w.network} network — assets sent on the wrong network can be lost for good.</p>
          </div>
        ))}
      </div>
      <p className="mt-3 rounded-xl bg-[var(--surface2)] px-3 py-2.5 text-xs leading-relaxed">
        <strong>Standing safety line:</strong> STONEMILES will <strong>never</strong> ask for a seed phrase, a
        private key, or a password — not in this app, not in a message, not anywhere, and never to enter or
        claim a giveaway. Anyone who does is not this team; it's a scam. Donate only from your own wallet, only
        an amount you're glad to give.
      </p>
      <p className="mt-2 rounded-xl bg-[var(--surface2)] px-3 py-2.5 text-xs leading-relaxed">
        <strong>Giveaways &amp; $STONER:</strong> the team runs giveaways from time to time — every official
        giveaway token has a verified contract address (CA) published on the Announcements Board on our site
        and in this app, where you can check it; if it isn't listed there, it isn't ours. If you're not sure,
        ask Meca for help. $STONER can lose all of its value, nothing we say is financial advice or a promise of
        profit, and to the fullest extent the law allows Stonervision is not liable for any loss connected with
        the token — see the full Disclaimer.
      </p>
    </InfoSheetShell>
  );
}

