                <div className="mt-3 flex flex-wrap gap-2">
                  <button type="button" className="btn-press rounded-xl bg-[var(--accent)] px-4 py-2.5 text-sm font-bold text-black" aria-label="Go to the console load board" onClick={() => setSection("board")}>🏢 Load Board</button>
                  <button type="button" className="btn-press rounded-xl border border-[var(--border)] bg-[var(--surface)] px-4 py-2.5 text-sm font-bold" aria-label="Go to fleet hours" onClick={() => setSection("hours")}>⏱️ Fleet Hours</button>
                  <button type="button" className="btn-press rounded-xl border border-[var(--border)] bg-[var(--surface)] px-4 py-2.5 text-sm font-bold" aria-label="Go to settlements and documents" onClick={() => setSection("settlements")}>🧾 Settlements</button>
                </div>
